pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BaseEscalationManager c;

    function setUp() public {
        c = new BaseEscalationManager();
    }

    function _testRequestPriceCaller(address caller, bytes32 identifier, uint256 time, bytes memory ancillaryData) internal {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c.optimisticAsserter()));
        bool reverted;
        (bool ok, ) = address(c).call(abi.encodeWithSelector(BaseEscalationManager.requestPrice.selector, identifier, time, ancillaryData));
        reverted = !ok;
        assertTrue(reverted);
    }

    function testFuzz_testRequestPriceCaller(address caller, bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
